INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17943$nota-0214$m17943$, $m17944$VO2 Max Essentials_Final.pdf$m17944$, $m17945$29$m17945$, $m17946$Exercise economy can vary significantly among individuals, with the oxygen cost of running or cycling at a given speed or power output differing by around 30%–40% and 20%–30%, respectively.$m17946$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17947$nota-0214$m17947$, $m17948$VO2 Max Essentials_Final.pdf$m17948$, $m17949$29$m17949$, $m17950$The efficiency is influenced by the velocity of muscle fiber shortening, with type I (slow twitch) muscle fibers displaying greater mechanical efficiency than type II (fast twitch) fibers. Elite endurance cyclists often possess a higher percentage of type I muscle fibers, which contribute to their improved efficiency. However, intense interval training can increase mitochondrial activity in both type I and type II muscle fibers, indicating that efficiency is not solely dependent on muscle fiber type.$m17950$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m17951$nota-0214$m17951$, $m17952$nota-0179$m17952$, $m17953$complementa$m17953$, $m17954$acrescenta a magnitude da variação individual (20-30% no ciclismo) e o papel da composição de fibras à definição de economia já registrada na nota-0179 (Fonte 2)$m17954$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17955$nota-0215$m17955$, $m17956$VO2 Max Essentials_Final.pdf$m17956$, $m17957$29$m17957$, $m17958$It was previously believed that cycling efficiency and running economy did not improve significantly with training. However, recent evidence suggests that running economy can improve over years of training even in elite athletes, with reported improvements ranging from 8% to 14%. Similarly, cycling efficiency has been observed to increase by approximately 8% over several years of training.$m17958$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m17959$nota-0215$m17959$, $m17960$nota-0179$m17960$, $m17961$complementa$m17961$, $m17962$acrescenta evidência de que a eficiência mecânica descrita na nota-0179 é treinável ao longo de anos, contrariando a crença anterior de que seria essencialmente fixa$m17962$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m17963$nota-0215$m17963$, $m17964$nota-0180$m17964$, $m17965$complementa$m17965$, $m17966$corpo da nota cita a lógica combinada 'economia se degrada com fadiga, mas melhora com treino consistente' registrada em nota-0179/nota-0180 — link estrutural a nota-0180 ausente até auditoria de 2026-08-02$m17966$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17967$nota-0228$m17967$, $m17968$Exercise Physiology McArdle.pdf$m17968$, $m17969$169$m17969$, $m17970$Table 7.1 Estimate of the Percent Contribution of Different Fuels to ATP Generation in Various Running Events (Assumes 70-kg Male) — 800 m: Phosphocreatine 6, Glycogen Anaerobic 50, Glycogen Aerobic 44. Marathon: Aerobic 75, Blood Glucose (Liver Glycogen) 5, Triacylglycerol (Fatty Acids) 20. Ultramarathon (80 km): Aerobic 35, Blood Glucose 5, Triacylglycerol 60. 24-h race: Aerobic 10, Blood Glucose 2, Triacylglycerol 88.$m17970$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17971$nota-0228$m17971$, $m17972$Exercise Physiology McArdle.pdf$m17972$, $m17973$169$m17973$, $m17974$From Newsholme EA, et al. Physical and mental fatigue: metabolic mechanisms and importance of plasma amino acids. Br Med Bull 1992;48:477.$m17974$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m17975$nota-0228$m17975$, $m17976$nota-0213$m17976$, $m17977$complementa$m17977$, $m17978$nota-0213 já registra a faixa geral de 10-20% de contribuição anaeróbia em eventos de 10-30min; esta tabela (Newsholme 1992, citada por McArdle) detalha a contribuição percentual específica por sistema energético (fosfocreatina, glicólise, aeróbio, glicose sanguínea, gordura) para uma escala completa de durações de evento, de 100m a 24h$m17978$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m17979$nota-0228$m17979$, $m17980$nota-0154$m17980$, $m17981$complementa$m17981$, $m17982$aplica os três sistemas de ressíntese de ATP definidos na nota-0154 a uma tabela concreta de contribuição percentual por duração de prova$m17982$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17983$nota-0229$m17983$, $m17984$Exercise Physiology McArdle.pdf$m17984$, $m17985$164$m17985$, $m17986$The oxygen deficit quantitatively expresses the difference between the total oxygen consumption during activity and the total that would be consumed had steady-rate oxygen consumption been achieved at the onset. This oxygen deficit represents the immediate anaerobic energy transfer from the hydrolysis of intramuscular high-energy phosphates and rapid glycolysis until steady-rate energy transfer matches the energy requirements.$m17986$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17987$nota-0229$m17987$, $m17988$Exercise Physiology McArdle.pdf$m17988$, $m17989$165$m17989$, $m17990$The endurance-trained person achieves steady rate more rapidly, with a smaller oxygen deficit than sprint-power athletes, cardiac patients, older adults, or untrained individuals. Consequently, a faster aerobic kinetic response allows the trained person to consume a greater total amount of oxygen to steady-rate exercise and makes the anaerobic component of energy transfer proportionately smaller.$m17990$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m17991$nota-0229$m17991$, $m17992$nota-0154$m17992$, $m17993$complementa$m17993$, $m17994$detalha, com o conceito de déficit de oxigênio, a fase de transição entre os sistemas de ressíntese de ATP (fosfagênio/glicolítico) e o sistema oxidativo já descritos na nota-0154$m17994$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17995$nota-0230$m17995$, $m17996$Exercise Physiology McArdle.pdf$m17996$, $m17997$207$m17997$, $m17998$Mechanical efficiency reflects the percentage of total chemical energy expended that contributes to external work, with the remainder lost as heat. Mechanical efficiency (%) = External work accomplished ÷ Energy expenditure × 100$m17998$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m17999$nota-0230$m17999$, $m18000$Exercise Physiology McArdle.pdf$m18000$, $m18001$208$m18001$, $m18002$Mechanical efficiency = 31.19 kcal ÷ 122.5 kcal × 100 = 25.5%... On average, mechanical efficiency ranges between 20 and 25% for walking, running, and stationary cycling... Efficiency falls below 20% for activities with substantial drag force that resists movement, as, for example, road cycling, cross-country skiing, ice skating, rowing, and swimming.$m18002$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m18003$nota-0230$m18003$, $m18004$nota-0179$m18004$, $m18005$complementa$m18005$, $m18006$fornece a fórmula quantitativa e um exemplo numérico completo para o conceito de economia/eficiência mecânica já definido qualitativamente na nota-0179$m18006$)
